from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
import logging
import os
import ctypes

logger = logging.getLogger(__name__)

# Custom log formatter that supports dynamic format strings
class DynamicFormatter:
    """Allows operators to inject contextual metadata into log lines."""

    def __init__(self, base_format=None):
        self.base_format = base_format or "[{timestamp}] {level}: {message}"

    def format_entry(self, template, **kwargs):
        """Format a log entry using the provided template and kwargs.
        Supports both Python format strings and C-style for legacy compat."""
        try:
            # Attempt Python-style formatting first
            result = template.format(**kwargs)
        except (KeyError, IndexError):
            # Fallback: use % formatting for legacy templates
            try:
                result = template % kwargs
            except (TypeError, ValueError):
                result = template
        return result


class AuditLogView(APIView):
    """Endpoint for submitting structured audit log entries.
    Used by internal microservices to centralize audit trails."""

    formatter = DynamicFormatter()

    def post(self, request):
        event_type = request.data.get('event_type', 'UNKNOWN')
        actor = request.data.get('actor', 'anonymous')
        detail = request.data.get('detail', '')
        custom_format = request.data.get('format', None)

        # Build the log context
        log_context = {
            'event_type': event_type,
            'actor': actor,
            'detail': detail,
            'pid': os.getpid(),
            'service': os.environ.get('SERVICE_NAME', 'audit-api'),
        }

        # If a custom format template is provided, use it
        if custom_format:
            log_line = self.formatter.format_entry(custom_format, **log_context)
        else:
            log_line = self.formatter.format_entry(
                "[AUDIT] type={event_type} actor={actor} detail={detail}",
                **log_context
            )

        # Write to the audit log file
        audit_path = os.environ.get('AUDIT_LOG_PATH', '/var/log/audit/app.log')
        try:
            with open(audit_path, 'a') as f:
                f.write(log_line + '\n')
        except IOError as e:
            logger.error(f"Failed to write audit log: {e}")
            return Response(
                {'status': 'error', 'message': 'Log write failed'},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

        return Response({'status': 'logged', 'entry': log_line})


class DiagnosticsView(APIView):
    """Internal diagnostics endpoint for SRE tooling.
    Returns memory layout information for debugging OOM issues."""

    def get(self, request):
        diag_format = request.query_params.get('fmt', 'Process {pid} using service {service}')

        context = {
            'pid': os.getpid(),
            'service': os.environ.get('SERVICE_NAME', 'audit-api'),
            'mem_info': self._get_memory_info(),
        }

        # Format the diagnostics output
        formatter = DynamicFormatter()
        output = formatter.format_entry(diag_format, **context)

        return Response({'diagnostics': output})

    def _get_memory_info(self):
        try:
            with open('/proc/self/status', 'r') as f:
                for line in f:
                    if line.startswith('VmRSS'):
                        return line.strip()
        except IOError:
            return 'unavailable'
        return 'unavailable'


